'use strict';
/**
 * 极简 CJS 打包器：把 server.js 的本地 require 图内联成单个文件
 * 只处理相对路径 require；Node 内置模块（fs/path/http…）原样保留。
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const ENTRY = path.join(ROOT, 'server.js');

const idOf = f => path.relative(ROOT, f).split(path.sep).join('/');

function resolveFile(fromFile, spec) {
  let p = path.resolve(path.dirname(fromFile), spec);
  if (fs.existsSync(p) && fs.statSync(p).isFile()) return p;
  if (fs.existsSync(p + '.js')) return p + '.js';
  if (fs.existsSync(path.join(p, 'index.js'))) return path.join(p, 'index.js');
  return null;
}

const modules = new Map();

function collect(file) {
  const id = idOf(file);
  if (modules.has(id)) return id;
  const src = fs.readFileSync(file, 'utf8');
  modules.set(id, ''); // 占位，避免循环引用时无限递归

  const out = src.replace(/require\(\s*(['"])([^'"]+)\1\s*\)/g, (m, q, spec) => {
    if (!spec.startsWith('.')) return m; // 内置模块保留
    const target = resolveFile(file, spec);
    if (!target) return m;
    collect(target);
    return '__req(' + JSON.stringify(idOf(target)) + ')';
  });

  modules.set(id, out);
  return id;
}

function bundle() {
  const entryId = collect(ENTRY);
  let body = '';
  for (const [id, code] of modules) {
    body += '\n__mods[' + JSON.stringify(id) + '] = function (module, exports, __req) {\n' + code + '\n};\n';
  }
  const head =
    '/* CyberRange bundle — generated by tools/bundle.js */\n' +
    '(function () {\n' +
    "  'use strict';\n" +
    '  var __mods = {};\n' +
    '  var __cache = {};\n' +
    '  function __req(id) {\n' +
    '    if (__cache[id]) return __cache[id].exports;\n' +
    '    var m = { exports: {} };\n' +
    '    __cache[id] = m;\n' +
    '    __mods[id](m, m.exports, __req);\n' +
    '    return m.exports;\n' +
    '  }\n';
  const tail = '\n  __req(' + JSON.stringify(entryId) + ');\n})();\n';
  return head + body + tail;
}

if (require.main === module) {
  const out = bundle();
  const target = path.join(ROOT, 'build', 'bundle.js');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, out, 'utf8');
  console.log('bundle -> ' + path.relative(ROOT, target) + '  (' + modules.size + ' modules, ' + (out.length / 1024).toFixed(1) + ' KB)');
}

module.exports = { bundle, ENTRY, ROOT };
